+func TestLiveShadowedRootKeyNoLongerCapsItsOwnStep(t *testing.T) {
+	agent := map[string]interface{}{"max_tokens": 2000.0, "ai_service": map[string]interface{}{"model": "claude-sonnet-5", "provider": "anthropic"}}
+	step := map[string]interface{}{"ai_service": map[string]interface{}{"max_tokens": 8000.0}}
+	got, from, shadowed := resolveBudgetKey("max_tokens", budgetLevelsForStep(agent, step, nil))
+	if got != 8000 {
+		t.Fatalf("the step declared 8000 in the canonical place and resolved to %d from %q — an agent-level leftover is capping its own step again", got, from)
+	}
+	if len(shadowed) != 1 || shadowed[0] != "root" {
+		t.Errorf("shadowed = %v, want [root] — the losing declaration must be named", shadowed)
